import{_ as e}from"./chunks/ai-settings-provider.Dh-uwgx_.js";import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.Boholvbs.js";const n="/docs/assets/ai-settings-knowledge-base.ZlKmmhCe.png",m=JSON.parse('{"title":"AI Settings","description":"","frontmatter":{},"headers":[],"relativePath":"ai-settings.md","filePath":"ai-settings.md"}'),s={name:"ai-settings.md"};function d(l,t,c,h,u,g){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="ai-settings" tabindex="-1">AI Settings <a class="header-anchor" href="#ai-settings" aria-label="Permalink to &quot;AI Settings&quot;">​</a></h1><p>JEO includes built-in AI capabilities for georeferencing posts, generating maps, and creating custom map layers. Before using these features, you need to configure an AI provider.</p><p>See <a href="./ai-in-jeo">AI in JEO</a> for an overview of the AI architecture and how each piece works.</p><h2 id="configuring-an-ai-provider" tabindex="-1">Configuring an AI provider <a class="header-anchor" href="#configuring-an-ai-provider" aria-label="Permalink to &quot;Configuring an AI provider&quot;">​</a></h2><p>Navigate to <strong>Jeo → AI</strong> in the WordPress dashboard. The settings page is organized into tabs:</p><h3 id="provider-tab" tabindex="-1">Provider tab <a class="header-anchor" href="#provider-tab" aria-label="Permalink to &quot;Provider tab&quot;">​</a></h3><p>Select one of the 10 supported AI providers and enter your API key:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Requires API key</th></tr></thead><tbody><tr><td>Google Gemini</td><td>Yes</td></tr><tr><td>OpenAI</td><td>Yes</td></tr><tr><td>DeepSeek</td><td>Yes</td></tr><tr><td>Anthropic</td><td>Yes</td></tr><tr><td>Ollama</td><td>No (local)</td></tr><tr><td>Mistral</td><td>Yes</td></tr><tr><td>ZAI</td><td>Yes</td></tr><tr><td>HuggingFace</td><td>Yes</td></tr><tr><td>Grok</td><td>Yes</td></tr><tr><td>Cohere</td><td>Yes</td></tr></tbody></table><p>After selecting a provider and entering the key, click <strong>Test Connection</strong> to verify it works.</p><p><img src="'+e+'" alt="AI Provider settings"></p><h3 id="knowledge-base-tab" tabindex="-1">Knowledge Base tab <a class="header-anchor" href="#knowledge-base-tab" aria-label="Permalink to &quot;Knowledge Base tab&quot;">​</a></h3><p>The Knowledge Base (RAG) stores vectorized versions of your posts and layers, allowing the AI to search for contextually relevant content when georeferencing or generating maps.</p><ul><li><strong>Embedding model</strong>: Choose an embedding model from your provider (or use Ollama locally).</li><li><strong>Auto-indexing</strong>: Automatically index new and updated posts/layers in the background.</li><li><strong>Batch size</strong>: Number of items processed per indexing cycle.</li><li><strong>Cron interval</strong>: How often the background indexing runs.</li><li><strong>Search results (topK)</strong>: Maximum number of semantic matches returned per search (1–50, default 10).</li><li><strong>Actions</strong>: Manually trigger indexing for posts or layers, backup/restore the vector store, or clear it.</li></ul><p><img src="'+n+'" alt="Knowledge Base settings"></p><h3 id="embedded-data-tab" tabindex="-1">Embedded Data tab <a class="header-anchor" href="#embedded-data-tab" aria-label="Permalink to &quot;Embedded Data tab&quot;">​</a></h3><p>JEO ships with built-in Brazilian geographic dictionaries (biomes, conservation units, indigenous lands, hydrographic basins, and more). These help the AI recognize geographic references in your content. This tab shows which dictionaries are loaded.</p><h3 id="bulk-geolocation-tab" tabindex="-1">Bulk Geolocation tab <a class="header-anchor" href="#bulk-geolocation-tab" aria-label="Permalink to &quot;Bulk Geolocation tab&quot;">​</a></h3><p>Configure batch geolocation settings for processing many posts at once. See <a href="./ai-bulk-geolocation">AI Bulk Geolocation</a> for details.</p><h3 id="context-assistant-tab" tabindex="-1">Context Assistant tab <a class="header-anchor" href="#context-assistant-tab" aria-label="Permalink to &quot;Context Assistant tab&quot;">​</a></h3><p>Customize the system prompt used by the <a href="./ai-context-assistant">AI Context Assistant</a> — the editorial suggestions sidebar in the Gutenberg editor.</p><ul><li><strong>Use custom prompt</strong>: Check this box to override the built-in default prompt with your own.</li><li><strong>Custom prompt</strong>: Editable textarea for your custom system prompt. When unchecked, the tab shows the default prompt in a read-only field for reference.</li></ul><p>Leave the custom prompt empty to use the built-in default, which is optimized for journalistic editorial assistance with RAG integration.</p><h2 id="structured-output" tabindex="-1">Structured output <a class="header-anchor" href="#structured-output" aria-label="Permalink to &quot;Structured output&quot;">​</a></h2><p>When enabled (default), the AI returns results in a strict JSON format enforced by the provider. This improves accuracy for georeferencing and map generation. You can disable it in the AI settings if your provider does not support it.</p><h2 id="cost-tracking" tabindex="-1">Cost tracking <a class="header-anchor" href="#cost-tracking" aria-label="Permalink to &quot;Cost tracking&quot;">​</a></h2><p>JEO tracks AI usage in <strong>Jeo → AI Debug Logs</strong>. Each log entry records the provider, model, input/output tokens, and the prompt and response. Use this to monitor costs and troubleshoot responses.</p>',26)])])}const f=a(s,[["render",d]]);export{m as __pageData,f as default};
